import{b as d,O as a,g as r,j as e}from"./chunks/framework.DSt9LnBW.js";const c=JSON.parse('{"title":"如何完美的设计一份测试用例？","description":"输入几乎是无限的，用例必须是有限的。设计方法要解决的就是这件事：用什么规则挑代表，才能既少写、又不把关键路径漏掉。知识星球里有具体的展开，见测试用例设计方法论。这篇不重复八要素模板，只做三件事：方法有哪些、每一项在同一张券上长什么样、它们彼此差在哪、什么时候叠用。白盒那一套（语句、分支、路径）从代码出发，见白盒与黑盒。下面谈的都是从需求出发的黑盒设计。","frontmatter":{"date":"2026-07-15T00:00:00.000Z","tags":["测试用例","等价类","边界值","用例设计"],"sidebar":false,"pageClass":"blog-post","prev":false,"next":false,"lastUpdated":false},"headers":[],"relativePath":"blog/testing/test-case-design-methods/index.md","filePath":"个人博客/测试/13.如何完美的设计一份测试用例？.md","lastUpdated":1791536854000}'),h={name:"blog/testing/test-case-design-methods/index.md"};function l(o,t,i,s,n,p){return a(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="如何完美的设计一份测试用例" tabindex="-1">如何完美的设计一份测试用例？ <a class="header-anchor" href="#如何完美的设计一份测试用例" aria-label="Permalink to &quot;如何完美的设计一份测试用例？&quot;">​</a></h1><p>输入几乎是无限的，用例必须是有限的。设计方法要解决的就是这件事：用什么规则挑代表，才能既少写、又不把关键路径漏掉。</p><p>知识星球里有具体的展开，见 <a href="/testing/basics/test-case-design/">测试用例设计方法论</a>。这篇不重复八要素模板，只做三件事：方法有哪些、每一项在同一张券上长什么样、它们彼此差在哪、什么时候叠用。</p><p>白盒那一套（语句、分支、路径）从代码出发，见 <a href="/testing/methodology/white-black-box/">白盒与黑盒</a>。下面谈的都是从需求出发的黑盒设计。</p><h2 id="先看全景" tabindex="-1">先看全景 <a class="header-anchor" href="#先看全景" aria-label="Permalink to &quot;先看全景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>它在问</th><th>适合什么</th><th>产出</th><th>容易漏什么</th></tr></thead><tbody><tr><td>等价类划分</td><td>哪些输入可以当成同一类</td><td>单字段、有取值范围</td><td>每类一个代表</td><td>类与类交界处的取值</td></tr><tr><td>边界值分析</td><td>刚好过线、刚好不过线测哪个</td><td>有 min / max、容量、时限</td><td>边界两侧的值</td><td>字段之间的组合</td></tr><tr><td>判定表</td><td>几个条件同时成立时走哪条规则</td><td>条件有与、或、互斥</td><td>一张规则表</td><td>系统当前处于什么状态</td></tr><tr><td>状态迁移</td><td>这个状态下允许什么操作</td><td>订单、券、审批、播放器</td><td>合法/非法转换</td><td>一条完整业务路径</td></tr><tr><td>场景法</td><td>用户从头到尾怎么走</td><td>主流程、分支、异常退出</td><td>基本流+备选流</td><td>单个字段的取值细节</td></tr><tr><td>成对测试</td><td>多因子组合怎么压缩</td><td>渠道、支付、配送这类正交因子</td><td>覆盖两两组合</td><td>三个因子同时踩中的坑</td></tr><tr><td>错误猜测</td><td>经验里哪里最容易炸</td><td>空值、并发、历史重灾区、特殊字符</td><td>一张风险清单</td><td>没有经验时会变成瞎测</td></tr></tbody></table><p>不是每个功能都要七种全上。输入长什么样，决定先用哪一种。</p><h2 id="贯穿例子-一张「满-100-减-20」" tabindex="-1">贯穿例子：一张「满 100 减 20」 <a class="header-anchor" href="#贯穿例子-一张「满-100-减-20」" aria-label="Permalink to &quot;贯穿例子：一张「满 100 减 20」&quot;">​</a></h2><p>后面每一节都对着同一张券。规则先写死，后面才谈得上「测哪个值」。</p><ul><li>订单金额（用券前）满 100 元才能用，减 20</li><li>每人限用 1 张，券码唯一</li><li>有生效时间和过期时间</li><li>券有状态：未生效、可使用、已锁定（下单未付）、已核销、已过期、已作废</li><li>结算时还要同时满足：已登录、商品有库存</li></ul><p>金额、条件组合、状态、下单路径、渠道支付，这张券都沾得到，所以拿它做对照最省事。</p><h2 id="_1-等价类划分-先分类-再各取一个代表" tabindex="-1">1. 等价类划分：先分类，再各取一个代表 <a class="header-anchor" href="#_1-等价类划分-先分类-再各取一个代表" aria-label="Permalink to &quot;1. 等价类划分：先分类，再各取一个代表&quot;">​</a></h2><p>同一类里的值，程序按同一套规则处理。类切对了，测一个就代表这一类；类切错了，后面边界值再密也是在错误的格子里打转。</p><p>对「订单金额」先切三刀：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>←──── 不可用券 ────│────── 可用券 ──────│</span></span>
<span class="line"><span>      (&lt; 100)     │      (≥ 100)      │</span></span></code></pre></div><p>金额不是唯一输入。券码、是否登录也要各自分类，无效类之间不要并成一堆——空券码和格式错误的券码，失败提示通常不是同一句。</p><table tabindex="0"><thead><tr><th>字段</th><th>有效类</th><th>无效类（各取一个代表）</th><th>代表值举例</th></tr></thead><tbody><tr><td>订单金额</td><td>≥ 100</td><td>＜ 100</td><td>150 / 80</td></tr><tr><td>券码</td><td>本账号下一张可用</td><td>空、格式错、别人的券、已用</td><td><code>A10020</code> / 空</td></tr><tr><td>登录态</td><td>已登录</td><td>未登录、登录过期</td><td>有效会话 / 无 cookie</td></tr></tbody></table><p>金额只取 150 和 80，只能说明「满不满 100」这一刀切对了没有。刚好 100 测不测，是下一节的事。</p><h2 id="_2-边界值-类划完了-取值往线上靠" tabindex="-1">2. 边界值：类划完了，取值往线上靠 <a class="header-anchor" href="#_2-边界值-类划完了-取值往线上靠" aria-label="Permalink to &quot;2. 边界值：类划完了，取值往线上靠&quot;">​</a></h2><p>开发写 <code>&gt;= 100</code> 时，最容易写成 <code>&gt; 100</code>，或者把分、元搞混。边界值不替代等价类，它只回答：这一类里，测哪个值最可能揭出 off-by-one。</p><p>金额有效范围按「满 100」来取：</p><table tabindex="0"><thead><tr><th>取值</th><th>位置</th><th>预期</th></tr></thead><tbody><tr><td>99.99</td><td>刚好无效</td><td>券不可用，原价</td></tr><tr><td>100.00</td><td>刚好有效</td><td>减 20，实付 80</td></tr><tr><td>100.01</td><td>有效内侧</td><td>减 20</td></tr></tbody></table><p>不只是数字：</p><ul><li>时间：过期时刻是当天 23:59:59，过期后的第一秒能不能核销</li><li>容量：每人限用 1 张，第二次提交应拒绝</li><li>状态：可使用变成已锁定的那一下，另一端再提交应失败</li></ul><p>等价类解决「测哪一类」，边界值解决「这一类里测哪一个」。两者几乎总是成对出现。</p><h2 id="_3-判定表-几个条件缠在一起时-别靠脑子穷举" tabindex="-1">3. 判定表：几个条件缠在一起时，别靠脑子穷举 <a class="header-anchor" href="#_3-判定表-几个条件缠在一起时-别靠脑子穷举" aria-label="Permalink to &quot;3. 判定表：几个条件缠在一起时，别靠脑子穷举&quot;">​</a></h2><p>金额达标、券可使用、已登录、有库存——四个条件同时成立才减 20。条件一多，口算组合一定会漏。因果图是把「与 / 或 / 非」画出来的草稿，真正能执行的是判定表。</p><p>四个是/否，完整表是 16 列。实际使用先删不可能组合（未登录却带着本账号的券），再合并结果相同的列。收完大概是这种粒度：</p><table tabindex="0"><thead><tr><th>条件 / 动作</th><th>R1</th><th>R2</th><th>R3</th><th>R4</th><th>R5</th></tr></thead><tbody><tr><td>已登录</td><td>是</td><td>是</td><td>是</td><td>是</td><td>否</td></tr><tr><td>金额 ≥ 100</td><td>是</td><td>否</td><td>是</td><td>是</td><td>—</td></tr><tr><td>券可使用</td><td>是</td><td>是</td><td>否</td><td>是</td><td>—</td></tr><tr><td>有库存</td><td>是</td><td>是</td><td>是</td><td>否</td><td>—</td></tr><tr><td>用券减 20</td><td>是</td><td>否</td><td>否</td><td>否</td><td>否</td></tr><tr><td>允许下单</td><td>是</td><td>是</td><td>是</td><td>否</td><td>否</td></tr><tr><td>提示</td><td>—</td><td>未满额</td><td>券不可用</td><td>库存不足</td><td>请登录</td></tr></tbody></table><p>判定表吃的是<strong>同一时刻的条件组合</strong>。它不回答「这张券昨天可用、今天过期」——那是状态问题。</p><h2 id="_4-状态迁移-同一张券-换个状态操作就变了" tabindex="-1">4. 状态迁移：同一张券，换个状态操作就变了 <a class="header-anchor" href="#_4-状态迁移-同一张券-换个状态操作就变了" aria-label="Permalink to &quot;4. 状态迁移：同一张券，换个状态操作就变了&quot;">​</a></h2><p>券不是一次性输入。未生效时核销、已核销后再用、下单未付时另一单再锁，合法输入也会走出非法转换。</p><table tabindex="0"><thead><tr><th>当前状态</th><th>事件</th><th>合法下一状态</th><th>非法操作（也要有用例）</th></tr></thead><tbody><tr><td>未生效</td><td>到生效时间</td><td>可使用</td><td>未生效就核销</td></tr><tr><td>可使用</td><td>下单未支付</td><td>已锁定</td><td>—</td></tr><tr><td>已锁定</td><td>支付成功</td><td>已核销</td><td>锁定中再被另一单使用</td></tr><tr><td>已锁定</td><td>取消 / 超时</td><td>可使用</td><td>—</td></tr><tr><td>可使用</td><td>过期</td><td>已过期</td><td>过期后核销</td></tr><tr><td>已核销</td><td>任意用券操作</td><td>保持已核销</td><td>重复核销</td></tr><tr><td>任一方</td><td>运营作废</td><td>已作废</td><td>作废后再用</td></tr></tbody></table><p>状态图测两件事：每条合法转换走得通；从每个状态出发的非法操作被拒绝，而且拒绝得干净（库存、金额不能半扣）。</p><p>判定表看的是某一帧的条件；状态迁移看的是帧和帧之间能不能跳。有生命周期的对象，两张表都要。</p><h2 id="_5-场景法-按用户路径串起来" tabindex="-1">5. 场景法：按用户路径串起来 <a class="header-anchor" href="#_5-场景法-按用户路径串起来" aria-label="Permalink to &quot;5. 场景法：按用户路径串起来&quot;">​</a></h2><p>前面几节都是切片：一个字段、一组条件、一次转换。用户感知到的是整条路径。场景法把路径拆成基本流和备选流。</p><p><strong>基本流</strong>：登录 → 加购满 100 → 选中这张券 → 支付成功 → 券已核销，实付减 20。</p><p><strong>备选流</strong>（每一条都是独立用例，不要全塞进基本流）：</p><table tabindex="0"><thead><tr><th>在哪一步分叉</th><th>发生什么</th><th>预期</th></tr></thead><tbody><tr><td>选券时</td><td>金额差 0.01</td><td>券置灰，仍可原价下单</td></tr><tr><td>支付前</td><td>库存被抢光</td><td>下单失败，券从锁定回到可使用</td></tr><tr><td>支付中</td><td>用户取消</td><td>订单取消，券解锁</td></tr><tr><td>支付成功后</td><td>申请退款</td><td>按退款规则决定券是否回补</td></tr></tbody></table><p>场景法保证「主路径能走通」，但不负责把金额的 99.99 / 100.00 测细——那仍然要回到边界值。路径覆盖和取值覆盖是两件事。</p><h2 id="_6-成对测试-因子多了-别-27-条全铺" tabindex="-1">6. 成对测试：因子多了，别 27 条全铺 <a class="header-anchor" href="#_6-成对测试-因子多了-别-27-条全铺" aria-label="Permalink to &quot;6. 成对测试：因子多了，别 27 条全铺&quot;">​</a></h2><p>结算页还可能叠三个相对独立的因子：下单渠道、支付方式、配送方式。各 3 个取值，全组合是 27 条。多数缺陷只需要<strong>两个因子同时取到特定值</strong>就会出现，三个因子同时踩中的少得多。成对测试要求任意两个因子的任意取值组合至少出现一次，三条因子的全组合可以丢掉。</p><p>下面 9 条已经覆盖全部两两组合：</p><table tabindex="0"><thead><tr><th>#</th><th>渠道</th><th>支付</th><th>配送</th></tr></thead><tbody><tr><td>1</td><td>App</td><td>微信</td><td>快递</td></tr><tr><td>2</td><td>App</td><td>支付宝</td><td>自提</td></tr><tr><td>3</td><td>App</td><td>余额</td><td>即时</td></tr><tr><td>4</td><td>H5</td><td>微信</td><td>自提</td></tr><tr><td>5</td><td>H5</td><td>支付宝</td><td>即时</td></tr><tr><td>6</td><td>H5</td><td>余额</td><td>快递</td></tr><tr><td>7</td><td>小程序</td><td>微信</td><td>即时</td></tr><tr><td>8</td><td>小程序</td><td>支付宝</td><td>快递</td></tr><tr><td>9</td><td>小程序</td><td>余额</td><td>自提</td></tr></tbody></table><p>正交表是生成这类组合的一种现成工具；日常说「成对」「两两」，指的是覆盖目标，不一定非要抱着正交表编号。</p><p>它压缩的是<strong>彼此独立的因子</strong>。券能不能用、金额满不满，条件之间有逻辑依赖，那种该用判定表，不要塞进成对。</p><h2 id="_7-错误猜测-系统性方法扫完再补经验" tabindex="-1">7. 错误猜测：系统性方法扫完再补经验 <a class="header-anchor" href="#_7-错误猜测-系统性方法扫完再补经验" aria-label="Permalink to &quot;7. 错误猜测：系统性方法扫完再补经验&quot;">​</a></h2><p>前面六种都从需求结构出发。总有一类问题需求里写得含糊，但你见过：空串当券码、金额为 0、两人同时锁同一张券。错误猜测是有方向的清单，不是想到哪测到哪。</p><p>对着这张券，清单可以是：</p><table tabindex="0"><thead><tr><th>方向</th><th>测什么</th><th>为什么值得猜</th></tr></thead><tbody><tr><td>空与零</td><td>券码空格、金额 0、数量 0</td><td>判空和「满额」常被写成一套</td></tr><tr><td>并发</td><td>同一张券两个请求同时提交</td><td>锁定不是数据库约束时会双核销</td></tr><tr><td>特殊字符</td><td>券码里的 <code>-</code>、空格、全角数字</td><td>复制粘贴、展示和存储不一致</td></tr><tr><td>时序</td><td>过期瞬间支付回调晚到</td><td>状态机和支付回调谁先谁后</td></tr><tr><td>历史坑</td><td>上次退款没有回补券的模块</td><td>缺陷爱扎堆</td></tr></tbody></table><p>没有历史、也问不到开发时，这一节的产量会很薄——那就老实用前六种打底，不要为了「看起来全面」编一堆没有依据的怪值。</p><h2 id="七种方法比什么" tabindex="-1">七种方法比什么 <a class="header-anchor" href="#七种方法比什么" aria-label="Permalink to &quot;七种方法比什么&quot;">​</a></h2><p>把同一张券上的分工摊开，差异比定义清楚：</p><table tabindex="0"><thead><tr><th></th><th>等价类</th><th>边界值</th><th>判定表</th><th>状态迁移</th><th>场景法</th><th>成对</th><th>错误猜测</th></tr></thead><tbody><tr><td>主要对象</td><td>单个输入域</td><td>域的端点</td><td>同一时刻的条件</td><td>对象生命周期</td><td>用户路径</td><td>独立因子</td><td>高风险点</td></tr><tr><td>典型问题</td><td>金额档位</td><td>99.99/100</td><td>登录×满额×库存</td><td>锁定/核销</td><td>下单到支付</td><td>渠道×支付</td><td>并发抢券</td></tr><tr><td>用例怎么长</td><td>每类一条</td><td>线上左右</td><td>一列一条规则</td><td>一条转换</td><td>一条流</td><td>一行组合</td><td>一条风险</td></tr><tr><td>相对成本</td><td>低</td><td>低</td><td>中，条件多就炸</td><td>中</td><td>中</td><td>低（相对全组合）</td><td>看经验</td></tr><tr><td>补谁的洞</td><td>—</td><td>补等价类</td><td>补「条件缠在一起」</td><td>补「有状态」</td><td>补「路径」</td><td>补「因子爆炸」</td><td>补系统方法扫不到的</td></tr><tr><td>替代不了谁</td><td>边界值</td><td>判定表</td><td>状态图</td><td>场景法</td><td>边界值</td><td>判定表</td><td>前六种</td></tr></tbody></table><p>几条容易混的关系，单独说清：</p><ol><li><strong>等价类和边界值是一套，不是二选一。</strong> 先分类，再把代表值改到边界上。只做等价类，100 和 99.99 往往被 150、80 代表掉；只做边界，无效类里「空券码」这种非数值问题进不来。</li><li><strong>判定表和成对不要抢活。</strong> 条件之间有「必须同时 / 互斥」，用判定表；渠道和支付彼此独立，用成对。把有依赖的条件丢进成对，压缩掉的可能恰好是那条会炸的规则。</li><li><strong>状态迁移和场景法一个看对象、一个看人。</strong> 状态图保证券不会从已核销跳回可使用；场景法保证用户从加购走到支付。两条都过，才是「路径合法且状态合法」。</li><li><strong>错误猜测排在最后，不是因为不重要，是因为它依赖前面积累的结构。</strong> 没有等价类和状态图，猜测清单不知道往哪贴。</li></ol><h2 id="面对一个功能-应该怎么选" tabindex="-1">面对一个功能，应该怎么选？ <a class="header-anchor" href="#面对一个功能-应该怎么选" aria-label="Permalink to &quot;面对一个功能，应该怎么选？&quot;">​</a></h2><p>按输入形态选，不按「方法清单还剩几个」选。</p><ol><li>先看有没有取值范围、格式、必填——<strong>等价类 + 边界值</strong>打底。搜索框、数量、金额、长度限制，到这一步往往已经够用。</li><li>同一提交动作依赖多个条件——补 <strong>判定表</strong>。勾选协议、验证码、权限开关都算。</li><li>对象有生命周期，同样的按钮在不同状态下含义不同——补 <strong>状态迁移</strong>。订单、券、账号冻结都是。</li><li>要验收的是一整段用户任务——补 <strong>场景法</strong>，主路径先封住。</li><li>三个以上彼此独立的配置项、渠道、环境——用 <strong>成对</strong> 压缩，不要 3×3×3 全铺。</li><li>最后拿历史缺陷、空值、并发、回调时序扫一遍——<strong>错误猜测</strong>。</li></ol><p>回到这张券：金额用等价类和边界值，结算条件用判定表，券生命周期用状态图，下单用场景，渠道支付配送用成对，抢券和过期回调用错误猜测。七种都出现，是因为这张券同时具备「有范围、有组合、有状态、有路径、有多因子」。换一个只有长度限制的密码框，前两种做完就可以停。</p><p>方法选多少取决于风险和复杂度，不取决于清单是否填满。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>用例设计是用规则挑代表：输入近乎无限，用例必须有限，漏的应是低风险取值，不是关键路径。</li><li>七种方法对象不同。等价类管「哪一类」，边界值管「这一类里哪个值」，判定表管同一时刻的条件组合，状态迁移管对象能不能跳，场景法管人怎么走完，成对管独立因子怎么压缩，错误猜测管经验里的高风险点。</li><li>几对关系不要拆开、也不要抢活：等价类和边界值成套用；有逻辑依赖用判定表，彼此独立用成对；状态图看对象，场景法看用户路径；错误猜测放在结构方法之后。</li><li>按输入形态选方法。有范围就打底，有组合、有状态、有路径、有多因子再往上叠。这张券七种都沾得到，密码框停在前两种就够。</li><li>「完美」不是清单填满，是该停的时候停、该补的时候补。选多少取决于风险和复杂度。</li></ul>`,64)])])}const g=d(h,[["render",l]]);export{c as __pageData,g as default};
